package wgmodern;
import java.util.*;import net.minecraft.world.item.*;import net.minecraft.world.item.context.UseOnContext;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.world.level.ClipContext;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.DispenserBlockEntity;import net.minecraft.core.*;import net.minecraft.world.phys.HitResult;import net.minecraft.core.dispenser.DefaultDispenseItemBehavior;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraftforge.common.capabilities.*;import net.minecraftforge.common.util.LazyOptional;import net.minecraftforge.fluids.*;import net.minecraftforge.fluids.capability.*;import net.minecraftforge.fluids.capability.templates.FluidHandlerItemStack;
public class CrystalCapsule extends Item {
 public CrystalCapsule(){super(new Properties());}
 @Override public String getDescriptionId(){return "item.WG_CrystalFlask";}
 @Override public ICapabilityProvider initCapabilities(ItemStack stack,CompoundTag nbt){return new FluidHandler(stack);}
 public static FluidStack fluid(ItemStack s){return FluidUtil.getFluidContained(s).orElse(FluidStack.EMPTY);}
 @Override public boolean hasCraftingRemainingItem(ItemStack s){return !fluid(s).isEmpty();}@Override public ItemStack getCraftingRemainingItem(ItemStack s){return new ItemStack(this);}
 @Override public void appendHoverText(ItemStack s,Level l,List<Component> text,TooltipFlag f){var fluid=fluid(s);if(!fluid.isEmpty())text.add(fluid.getDisplayName());}
 @Override public InteractionResult useOn(UseOnContext c){if(c.getPlayer()==null)return InteractionResult.PASS;if(!FluidUtil.getFluidHandler(c.getLevel(),c.getClickedPos(),c.getClickedFace()).isPresent())return InteractionResult.PASS;if(c.getLevel().isClientSide)return InteractionResult.SUCCESS;if(FluidUtil.interactWithFluidHandler(c.getPlayer(),c.getHand(),c.getLevel(),c.getClickedPos(),c.getClickedFace()))return InteractionResult.CONSUME;return InteractionResult.PASS;}
 @Override public InteractionResultHolder<ItemStack> use(Level l,Player p,InteractionHand hand){var held=p.getItemInHand(hand);var hit=getPlayerPOVHitResult(l,p,fluid(held).isEmpty()?ClipContext.Fluid.SOURCE_ONLY:ClipContext.Fluid.NONE);if(hit.getType()!=HitResult.Type.BLOCK)return InteractionResultHolder.pass(held);var pos=hit.getBlockPos();if(!l.mayInteract(p,pos)||!p.mayUseItemAt(pos.relative(hit.getDirection()),hit.getDirection(),held))return InteractionResultHolder.fail(held);if(l.isClientSide)return InteractionResultHolder.success(held);if(FluidUtil.interactWithFluidHandler(p,hand,l,pos,hit.getDirection()))return InteractionResultHolder.consume(p.getItemInHand(hand));var result=change(l,fluid(held).isEmpty()?pos:pos.relative(hit.getDirection()),held,p,hand,hit.getDirection());if(!result.isEmpty()){held.shrink(1);if(held.isEmpty())return InteractionResultHolder.consume(result);if(!p.getInventory().add(result))p.drop(result,false);return InteractionResultHolder.consume(held);}return InteractionResultHolder.pass(held);}
 public static ItemStack change(Level l,BlockPos pos,ItemStack s,Player p,InteractionHand hand,Direction face){var f=fluid(s);var one=s.copyWithCount(1);FluidActionResult result=f.isEmpty()?FluidUtil.tryPickUpFluid(one,p,l,pos,face):FluidUtil.tryPlaceFluid(p,l,hand,pos,one,f);return result.isSuccess()?result.getResult():ItemStack.EMPTY;}
 public static class FluidHandler extends FluidHandlerItemStack {
  public FluidHandler(ItemStack s){super(s,1000);}
  @Override public int fill(FluidStack r,FluidAction action){if(container.getCount()!=1||!getFluid().isEmpty()||r.getAmount()<1000)return 0;var portion=r.copy();portion.setAmount(1000);return super.fill(portion,action);}
  @Override public FluidStack drain(int amount,FluidAction action){return container.getCount()==1&&amount>=1000&&getFluid().getAmount()==1000?super.drain(1000,action):FluidStack.EMPTY;}
  @Override public FluidStack drain(FluidStack resource,FluidAction action){return resource.getAmount()>=1000&&resource.isFluidEqual(getFluid())?drain(1000,action):FluidStack.EMPTY;}
 }
 public static void initDispenser(){DispenserBlock.registerBehavior(Content.CAPSULE.get(),new DefaultDispenseItemBehavior(){private final DefaultDispenseItemBehavior eject=new DefaultDispenseItemBehavior();@Override protected ItemStack execute(BlockSource source,ItemStack stack){var face=source.getBlockState().getValue(DispenserBlock.FACING);var result=change(source.getLevel(),source.getPos().relative(face),stack,null,InteractionHand.MAIN_HAND,face);if(result.isEmpty())return super.execute(source,stack);stack.shrink(1);if(stack.isEmpty())return result;var dispenser=(DispenserBlockEntity)source.getEntity();if(dispenser.addItem(result)<0)eject.dispense(source,result);return stack;}});}
}
